fulfill.run:
const re = $self.address.entire; $utils.setAsBlockRoot($self)
const INDEX_KEY = '__DO_NOT_USE_THIS_PROPERTY_index__'
const PAGE_ID_PREFIX = 'pageId_'
$self.state = $observable({ loading: false, list: [], drawerStatus: '隐藏', currentItem: null })
$self.cleanRow = (row) => {
  const c = {}
  Object.keys(row || {}).forEach((k) => {
    if (k !== INDEX_KEY && !k.endsWith('Display')) c[k] = row[k]
  })
  return c
}
$self.getNewPageDefaultSchema = async (pageId) => {
  const assistantConfig = await $utils.getAssistantConfig()
  if (!assistantConfig) {
    $message.error('获取扩展配置信息失败')
    throw new Error('获取扩展配置信息失败')
  }
  const defaultSchemaMap = assistantConfig.defaultSchema || {}
  const url = defaultSchemaMap[pageId] || defaultSchemaMap['demo']
  if (!url) {
    $message.error('未找到默认页面配置，请检查扩展配置中的 defaultSchema')
    throw new Error('未找到默认页面配置')
  }
  try {
    return await (await $chrome.fetch(url)).json()
  } catch (e) {
    $message.error('获取默认页面配置失败')
    throw new Error('获取默认页面配置失败')
  }
}
$self.refreshList = async () => {
  try {
    $self.state.loading = true
    const record = (await $chrome.storage.local.get()) || {}
    const result = []
    Object.keys(record).forEach((key) => {
      if (key.startsWith(PAGE_ID_PREFIX)) {
        result.push(record[key])
      }
    })
    const knownPages = [
      ['elementsSidebarPane', '元素边栏面板页'],
      ['devtoolsPanel', '开发者面板页'],
      ['sidePanel', '边栏页'],
      ['popup', '弹出式窗口'],
      ['newtab', '新标签页'],
      ['demo', '各种示例(待完善)'],
    ]
    const createPromises = knownPages.map(([pageId, name]) => {
      if (result.find((p) => p.id === pageId)) return Promise.resolve(null)
      return $self.getNewPageDefaultSchema(pageId)
        .then((defaultSchema) => {
          const newPage = { id: pageId, name: name, desc: name, jsonSchema: JSON.stringify(defaultSchema), isBuiltIn: true }
          return $chrome.storage.local.set({ [PAGE_ID_PREFIX + pageId]: newPage }).then(() => newPage)
        })
        .catch((e) => {
          $logger.warn('创建内置页面失败: ' + pageId, e)
          return null
        })
    })
    const createdPages = (await Promise.all(createPromises)).filter(Boolean)
    createdPages.forEach((p) => result.unshift(p))
    $self.state.list = result
      .sort((a, b) => (b.updateTime || 0) - (a.updateTime || 0))
      .map((p) => ({
        ...p,
        updateTimeDisplay: p.updateTime ? $dayjs(p.updateTime).format('YYYY-MM-DD HH:mm:ss') : '',
      }))
  } catch (e) {
    $logger.error('请求页面列表失败', e)
    $message.error('请求页面列表失败')
  } finally {
    $self.state.loading = false
  }
}
$self.savePage = async (page) => {
  page = $self.cleanRow(page)
  await $chrome.storage.local.set({ [PAGE_ID_PREFIX + page.id]: { ...page, updateTime: Date.now() } })
}
$self.removePage = async (id) => {
  await $chrome.storage.local.remove(PAGE_ID_PREFIX + id)
}
$self.openLowCodeEditorPage = async (lowCodeType, record) => {
  let url = 'lowcode.html?lowCodeType=' + lowCodeType + '&pageId=' + record.id
  const devWeb = $utils.getQueryString('devWeb')
  if (devWeb === '1') {
    url += '&devWeb=1'
  }
  url = await $chrome.runtime.getURL(url)
  await $chrome.tabs.create({ url: url })
}
$self.showDrawer = (row, status) => {
  const dialog = $self.query(re + '.editDrawer').take()
  if (!dialog) return
  $self.state.currentItem = row ? $self.cleanRow(row) : null
  $self.state.drawerStatus = status
  dialog.value = row ? { name: row.name, desc: row.desc } : { name: '', desc: '' }
  dialog.setPattern('editable')
  dialog.setComponentProps({ open: true, title: status + '页面' })
}
$self.dismissDrawer = () => {
  $self.state.drawerStatus = '隐藏'
  $self.state.currentItem = null
  const dialog = $self.query(re + '.editDrawer').take()
  if (dialog) dialog.componentProps.open = false
}
$self.handleSaveDrawer = () => {
  const dialog = $self.query(re + '.editDrawer').take()
  if (!dialog) return
  dialog
    .validate()
    .then(async () => {
      const form = dialog.value || {}
      const status = $self.state.drawerStatus
      if (status === '新增') {
        try {
          const defaultSchema = await $self.getNewPageDefaultSchema(form.name)
          await $self.savePage({ name: form.name, desc: form.desc, id: $dayjs().format('YYYYMMDDHHmmssSSS'), jsonSchema: JSON.stringify(defaultSchema), isBuiltIn: false })
          $message.success('新增页面成功')
          $self.dismissDrawer()
          $self.refreshList()
        } catch (e) {
          $message.error('新增页面失败')
        }
      } else if (status === '编辑') {
        try {
          await $self.savePage({ ...$self.state.currentItem, ...form })
          $message.success('编辑页面基础信息成功')
          $self.dismissDrawer()
          $self.refreshList()
        } catch (e) {
          $message.error('编辑页面基础信息失败')
        }
      }
    })
    .catch((e) => $logger.info('校验失败', e))
}
$effect(() => {
  $self.refreshList()
  try {
    $utils.getVipConfig()
  } catch (e) {}
}, [])

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({
  onClick: async () => {
    const { canceled, result } = await $utils.importJsonFromFile()
    if (canceled || !result) return
    const arr = Array.isArray(result) ? result : [result]
    if (arr.length === 0) {
      $message.error('从文件导入的内容为空')
      return
    }
    for (let i = 0; i < arr.length; i++) {
      const p = arr[i]
      if (!p || !p.id || !p.name || !p.desc || !p.jsonSchema) {
        $message.error('第 ' + (i + 1) + ' 个页面格式错误，已终止导入')
        return
      }
      try {
        JSON.parse(p.jsonSchema)
      } catch (e) {
        $message.error('第 ' + (i + 1) + ' 个页面的 jsonSchema 格式错误，已终止导入')
        return
      }
    }
    try {
      for (const p of arr) {
        await rf.savePage(p)
      }
      await rf.refreshList()
      $message.success('批量导入页面成功，共 ' + arr.length + ' 个')
    } catch (e) {
      $logger.error('批量导入页面失败', e)
      $message.error('批量导入页面失败：' + (e && e.message ? e.message : String(e)))
    }
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({
  onClick: async () => {
    const list = rf.state.list || []
    if (list.length === 0) {
      $message.error('没有可导出的页面')
      return
    }
    let extName = '上帝小助手'
    try {
      const manifest = await $chrome.runtime.getManifest()
      extName = (manifest && manifest.name) || extName
    } catch (e) {}
    const data = list.map((item) => rf.cleanRow(item))
    $utils.exportJsonToFile(JSON.stringify(data), extName + '导出页面-' + list.length + '个-' + $dayjs().format('YYYYMMDD_HHmmss') + '.json')
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => rf.showDrawer(null, '新增') })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $props({ disabled: !!(row && row.isBuiltIn) })
}, [rf.state.list])
$props({
  onConfirm: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    try {
      await rf.removePage(row.id)
      $message.success('删除页面成功')
      rf.refreshList()
    } catch (e) {
      $message.error('删除页面失败')
    }
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); if (row) rf.showDrawer(row, '编辑') } })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); if (row) rf.openLowCodeEditorPage('preview', row) } })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); if (row) rf.openLowCodeEditorPage('editor', row) } })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    try {
      const newPage = { ...rf.cleanRow(row), name: row.name + '-副本', desc: row.desc + '-副本', id: $dayjs().format('YYYYMMDDHHmmssSSS'), isBuiltIn: false }
      await rf.savePage(newPage)
      $message.success('复制页面成功')
      await rf.refreshList()
      rf.showDrawer(newPage, '编辑')
    } catch (e) {
      $message.error('复制页面失败')
    }
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    const extName = '上帝小助手'
    $utils.exportJsonToFile(JSON.stringify(rf.cleanRow(row)), extName + '导出页面-' + row.id + '-' + (row.name || '').replace(/[\\/:*?"<>|]/g, '_') + '-' + $dayjs().format('YYYYMMDD_HHmmss') + '.json')
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    const { canceled, result } = await $utils.importJsonFromFile()
    if (canceled) return
    if (!result || !result.id || !result.name || !result.desc || !result.jsonSchema) {
      $message.error('从文件导入的内容格式错误')
      return
    }
    try {
      JSON.parse(result.jsonSchema)
    } catch (e) {
      $message.error('从文件导入的内容格式错误')
      return
    }
    if (result.id === row.id) {
      try {
        await rf.savePage({ ...result, isBuiltIn: row.isBuiltIn })
        $message.success('从文件导入页面成功')
        rf.refreshList()
      } catch (e) {
        $message.error('从文件导入页面失败')
      }
    } else {
      $modal.confirm({
        title: '从文件导入页面「' + result.name + '」的 id「' + result.id + '」和当前选中的页面「' + row.name + '」的 id「' + row.id + '」不同，确认导入除 id 以外的页面信息吗？',
        okText: '确认',
        onOk: async () => {
          try {
            await rf.savePage({ ...result, id: row.id, isBuiltIn: row.isBuiltIn })
            $message.success('从文件导入页面成功')
            rf.refreshList()
          } catch (e) {
            $message.error('从文件导入页面失败')
          }
        },
      })
    }
  },
})

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClose: () => rf.dismissDrawer() })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => rf.dismissDrawer() })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$props({ onClick: () => rf.handleSaveDrawer() })
